<?php
    $nodeStmt = db()->query("
        SELECT
            id,
            node_group,
            node_name,
            node_location,
            node_status,
            status_class,
            node_specs,
            map_left,
            map_top
        FROM node_locations
        WHERE is_active = 1
        ORDER BY sort_order ASC, id ASC
    ");

    $mapNodes = $nodeStmt->fetchAll();
?>

