<?php

$stmt = db()->query("
    SELECT id, slug, title, excerpt, image_url, published_at
    FROM articles
    WHERE is_published = 1
    ORDER BY published_at DESC, id DESC
    LIMIT 3
");

$articles = $stmt->fetchAll();
?>

<section id="news" class="news">
    <h2>Latest News</h2>

    <?php if (!empty($articles)): ?>
        <?php foreach ($articles as $article): ?>
            <div class="news-item">
                <div class="news-content">
                    <h3>
                        <a href="/page.php?name=news">
                            <?= htmlspecialchars($article['title']) ?>
                        </a>
                    </h3>
                    <p class="news-date">
                        <?= !empty($article['published_at']) ? date('F j, Y @ g:i A T', strtotime($article['published_at'])) : '' ?>
                    </p>
                    <?= $article['excerpt'] ?? '' ?>
                </div>
            </div>
        <?php endforeach; ?>
    <?php endif; ?>
</section>

<script>
    document.addEventListener('DOMContentLoaded', function () {
        const scrollLink = document.getElementById('scrollToServers');
        const serversSection = document.getElementById('servers');

        if (scrollLink && serversSection) {
            scrollLink.addEventListener('click', function (e) {
                e.preventDefault();
                serversSection.scrollIntoView({
                    behavior: 'smooth',
                    block: 'start'
                });
            });
        }
    });
</script>